create table if not exists public.shop_applications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, shop_name text not null, phone text not null, city text not null, latitude double precision not null, longitude double precision not null, address text, verification_status text not null default 'pending' check (verification_status in ('pending','approved','rejected')), liveness_status text not null default 'pending_provider', identity_match_status text not null default 'pending_provider', reviewer_id uuid references auth.users(id), rejection_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.shop_applications enable row level security;
create policy "shop_applications_owner_select" on public.shop_applications for select to authenticated using (auth.uid() = user_id or exists (select 1 from public.profiles p where p.id = auth.uid() and p.is_admin = true));
create policy "shop_applications_owner_insert" on public.shop_applications for insert to authenticated with check (auth.uid() = user_id);
create policy "shop_applications_admin_update" on public.shop_applications for update to authenticated using (exists (select 1 from public.profiles p where p.id = auth.uid() and p.is_admin = true)) with check (exists (select 1 from public.profiles p where p.id = auth.uid() and p.is_admin = true));
create index if not exists shop_applications_user_id_idx on public.shop_applications(user_id);
create index if not exists shop_applications_status_idx on public.shop_applications(verification_status);
